window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-68dde4c4b6a40b10"]={"versions": [{"id": "FIG-68dde4c4b6a40b10", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> SPEM 2.0 (Software &amp; Systems Process Engineering Metamodel) Task-Definitions- und Rollenzuweisungsdiagramm gemäß <code>AUTOSAR_TR_Methodology</code> (Package <code>AUTOSAR Root::M2::Methodology::Methodology Library::System::Tasks</code>).\n</li><li><strong>Architektur-Kontext:</strong> Methodische Verankerung im System- und Kommunikationsentwurf der AUTOSAR Classic Platform. Das Diagramm definiert den formalen Prozessschritt zur Erstellung der Spezifikation für anwenderspezifische Datentransformatoren (<em>Custom Transformers</em>). Diese erweitern die standardisierten RTE- und Kommunikationsmechanismen (z. B. SOME/IP-, E2E- oder SecOC-Transformer) um proprietäre Serialisierungs-, Kompressions-, Verschlüsselungs- oder Protokollanpassungslogik direkt im Datenpfad der RTE (<code>Rte_Send</code> / <code>Rte_Receive</code> bzw. <code>Rte_Write</code> / <code>Rte_Read</code>).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Task Definition (Aktivitätsknoten):</strong>\n<ul class=\"fig-list\"><li><code>Create Transformer Specification</code>: Elementare SPEM-Aktivität (Chevron-Symbol). Kapselt die funktionale, mathematische und algorithmische Ausarbeitung des Verhaltens, des Frame-/Header-Layouts sowie der Schnittstellengeometrie des Transformers.\n</li></ul>\n</li><li><strong>Akteure / Rollen (SPEM Process Roles):</strong>\n<ul class=\"fig-list\"><li><code>System Engineer</code> (Akteur links): Primär verantwortlicher System- und Kommunikationsarchitekt; integriert die Transformationsanforderungen in die übergeordnete Signal-, Port- und Topologieplanung.\n</li><li><code>Basic Software Designer</code> (Akteur rechts): BSW-Architekt; liefert die hardware- und stacknahe Expertise bezüglich Laufzeiteffizienz, Speichermodellen und Betriebssystemkontexten.\n</li></ul>\n</li><li><strong>Arbeitsergebnis (SPEM Work Product / Deliverable):</strong>\n<ul class=\"fig-list\"><li><code>Custom Transformer Specification</code> (Dokumenten-Symbol unten rechts): Das verbindliche Spezifikationsdokument, welches als Entwicklungs- und Implementierungsgrundlage dient.\n</li></ul>\n</li><li><strong>Stereotypen, gerichtete Kanten &amp; Kardinalitäten:</strong>\n<ul class=\"fig-list\"><li><code>«performs»</code> von <code>System Engineer</code> zu <code>Create Transformer Specification</code> mit Kardinalität <code>1</code>: Obligatorische Federführung durch genau einen Systemingenieur.\n</li><li><code>«performs»</code> von <code>Basic Software Designer</code> zu <code>Create Transformer Specification</code> mit Kardinalität <code>0..1</code>: Optionale Mitwirkung zur Absicherung der Plattform- und BSW-Konformität.\n</li><li><code>«output»</code> von <code>Create Transformer Specification</code> zu <code>Custom Transformer Specification</code> mit Kardinalität <code>1</code>: Deterministisches Pflicht-Artefakt als Ergebnis der Task.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als SPEM-Strukturdiagramm bildet das Modell primär Prozessbeziehungen ab; die methodische Ausführung folgt folgendem deterministischen Ablauf:</p>\n<ol class=\"fig-list\"><li><strong>Trigger / Vorbedingung:</strong>\n<ul class=\"fig-list\"><li>Identifikation spezieller Datenübertragungsanforderungen im Systemdesign (z. B. Payload-Verschlüsselung, herstellerspezifische Prüfsummen oder Serialisierung komplexer Datentypen über Partitions- oder Busgrenzen hinweg), die nicht durch Standard-Transformer abgedeckt sind.\n</li></ul>\n</li><li><strong>Kollaborative Ausarbeitung (<code>Create Transformer Specification</code>):</strong>\n<ul class=\"fig-list\"><li><strong>System Engineer:</strong> Definiert das Protokollformat, Datenrepräsentationen, Serialisierungsregeln, Byte-Orderings, Pufferanforderungen und das Fehlerverhalten.\n</li><li><strong>Basic Software Designer (falls beteiligt, <code>0..1</code>):</strong> Validiert Pufferkonzepte (<em>in-place</em> vs. <em>out-of-place</em>), Reentrancy, Ausführungsbudgets im Kontext der OS-Tasks sowie die Stack-Auslastung.\n</li></ul>\n</li><li><strong>Artefakt-Erstellung (<code>«output» 1</code>):</strong>\n<ul class=\"fig-list\"><li>Generierung der <code>Custom Transformer Specification</code>.\n</li></ul>\n</li><li><strong>Nachgelagerte Prozessschritte (Downstream):</strong>\n<ul class=\"fig-list\"><li>Dient als direkte Eingabe für die Aktivität <code>Define Vendor Specific Module Definition</code> (Erstellung der BSWMD / <code>EcucModuleDef</code> für Konfigurationstools).\n</li><li>Dient als Vorlage für die C-Code-Implementierung des BSW-Treibermoduls sowie die Definition der <code>TransformationTechnology</code> in der System Description (ARXML).\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>API-Vertrag (<code>AUTOSAR_SWS_TransformerGeneral</code>):</strong>\n<ul class=\"fig-list\"><li>Die resultierende Spezifikation muss zwingend die standardisierten C-Funktionsprototypen gemäß AUTOSAR-Vorgabe vorschreiben:\n<ul class=\"fig-list\"><li>Vorwärtstransformation: <code>&lt;TransformerName&gt;_Transform(..., uint8* buffer, uint32* bufferLength, ...)</code>\n</li><li>Rückwärtstransformation: <code>&lt;TransformerName&gt;_InvTransform(..., const uint8* buffer, uint32 bufferLength, ...)</code>\n</li></ul>\n</li><li>Rückgabewerte müssen dem AUTOSAR-spezifischen Fehlerschema genügen (<code>E_OK</code>, <code>E_SER_GENERIC_ERROR</code>, herstellerspezifische Fehlerbits bzw. Severity-Klassen).\n</li></ul>\n</li><li><strong>Speicher- und Pufferstrategie:</strong>\n<ul class=\"fig-list\"><li>Klare Definition, ob der Transformer <em>in-place</em> (modifiziert den bestehenden Puffer) oder <em>out-of-place</em> (erfordert Allokation eines separaten Zielpuffers durch die RTE) arbeitet.\n</li><li>Im Embedded-Bereich müssen deterministische Obergrenzen für Puffergrößen (<code>bufferLength</code>) statisch zur Generierungszeit konfigurierbar sein; dynamische Speicherallokationen (<code>malloc</code>) sind strikt unzulässig.\n</li></ul>\n</li><li><strong>RTE-Integration &amp; Chain-Orchestrierung:</strong>\n<ul class=\"fig-list\"><li>Die RTE bindet Transformer-Aufrufe direkt in die Inline- oder Stub-Funktionen der Ports ein.\n</li><li>Sollen mehrere Transformer hintereinandergeschaltet werden (z. B. Custom-Serializer gefolgt von E2E-Protection), muss die Spezifikation die Position in der <code>TransformerChain</code> und die Pufferweitergabe mit den korrekten Alignment- und Padding-Restriktionen normieren.\n</li></ul>\n</li><li><strong>Reentrancy &amp; Interrupt-Sicherheit:</strong>\n<ul class=\"fig-list\"><li>Die Spezifikation muss festlegen, ob die Transformationsroutinen reentrant sein müssen, wenn dieselbe Transformer-Instanz parallel von unterschiedlichen SW-C-Tasks oder Interrupt-Kontexten aufgerufen werden kann.\n</li></ul>\n</li></ul>"}, {"id": "FIG-ce92223d344d2fc8", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> SPEM 2.0 (Software &amp; Systems Process Engineering Metamodel) Task-Definitions- und Rollenzuweisungsdiagramm gemäß <code>AUTOSAR_TR_Methodology</code> (Package <code>AUTOSAR Root::M2::Methodology::Methodology Library::System::Tasks</code>).\n</li><li><strong>Architektur-Kontext:</strong> Methodische Verankerung im System- und Kommunikationsentwurf der AUTOSAR Classic Platform. Das Diagramm definiert den formalen Prozessschritt zur Erstellung der Spezifikation für anwenderspezifische Datentransformatoren (<em>Custom Transformers</em>). Diese erweitern die standardisierten RTE- und Kommunikationsmechanismen (z. B. SOME/IP-, E2E- oder SecOC-Transformer) um proprietäre Serialisierungs-, Kompressions-, Verschlüsselungs- oder Protokollanpassungslogik direkt im Datenpfad der RTE (<code>Rte_Send</code> / <code>Rte_Receive</code> bzw. <code>Rte_Write</code> / <code>Rte_Read</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Task Definition (Aktivitätsknoten):</strong>\n<ul class=\"fig-list\"><li><code>Create Transformer Specification</code>: Elementare SPEM-Aktivität (Chevron-Symbol). Kapselt die funktionale, mathematische und algorithmische Ausarbeitung des Verhaltens, des Frame-/Header-Layouts sowie der Schnittstellengeometrie des Transformers.\n</li></ul>\n</li><li><strong>Akteure / Rollen (SPEM Process Roles):</strong>\n<ul class=\"fig-list\"><li><code>System Engineer</code> (Akteur links): Primär verantwortlicher System- und Kommunikationsarchitekt; integriert die Transformationsanforderungen in die übergeordnete Signal-, Port- und Topologieplanung.\n</li><li><code>Basic Software Designer</code> (Akteur rechts): BSW-Architekt; liefert die hardware- und stacknahe Expertise bezüglich Laufzeiteffizienz, Speichermodellen und Betriebssystemkontexten.\n</li></ul>\n</li><li><strong>Arbeitsergebnis (SPEM Work Product / Deliverable):</strong>\n<ul class=\"fig-list\"><li><code>Custom Transformer Specification</code> (Dokumenten-Symbol unten rechts): Das verbindliche Spezifikationsdokument, welches als Entwicklungs- und Implementierungsgrundlage dient.\n</li></ul>\n</li><li><strong>Stereotypen, gerichtete Kanten &amp; Kardinalitäten:</strong>\n<ul class=\"fig-list\"><li><code>«performs»</code> von <code>System Engineer</code> zu <code>Create Transformer Specification</code> mit Kardinalität <code>1</code>: Obligatorische Federführung durch genau einen Systemingenieur.\n</li><li><code>«performs»</code> von <code>Basic Software Designer</code> zu <code>Create Transformer Specification</code> mit Kardinalität <code>0..1</code>: Optionale Mitwirkung zur Absicherung der Plattform- und BSW-Konformität.\n</li><li><code>«output»</code> von <code>Create Transformer Specification</code> zu <code>Custom Transformer Specification</code> mit Kardinalität <code>1</code>: Deterministisches Pflicht-Artefakt als Ergebnis der Task.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als SPEM-Strukturdiagramm bildet das Modell primär Prozessbeziehungen ab; die methodische Ausführung folgt folgendem deterministischen Ablauf:</p>\n<ol class=\"fig-list\"><li><strong>Trigger / Vorbedingung:</strong>\n<ul class=\"fig-list\"><li>Identifikation spezieller Datenübertragungsanforderungen im Systemdesign (z. B. Payload-Verschlüsselung, herstellerspezifische Prüfsummen oder Serialisierung komplexer Datentypen über Partitions- oder Busgrenzen hinweg), die nicht durch Standard-Transformer abgedeckt sind.\n</li></ul>\n</li><li><strong>Kollaborative Ausarbeitung (<code>Create Transformer Specification</code>):</strong>\n<ul class=\"fig-list\"><li><strong>System Engineer:</strong> Definiert das Protokollformat, Datenrepräsentationen, Serialisierungsregeln, Byte-Orderings, Pufferanforderungen und das Fehlerverhalten.\n</li><li><strong>Basic Software Designer (falls beteiligt, <code>0..1</code>):</strong> Validiert Pufferkonzepte (<em>in-place</em> vs. <em>out-of-place</em>), Reentrancy, Ausführungsbudgets im Kontext der OS-Tasks sowie die Stack-Auslastung.\n</li></ul>\n</li><li><strong>Artefakt-Erstellung (<code>«output» 1</code>):</strong>\n<ul class=\"fig-list\"><li>Generierung der <code>Custom Transformer Specification</code>.\n</li></ul>\n</li><li><strong>Nachgelagerte Prozessschritte (Downstream):</strong>\n<ul class=\"fig-list\"><li>Dient als direkte Eingabe für die Aktivität <code>Define Vendor Specific Module Definition</code> (Erstellung der BSWMD / <code>EcucModuleDef</code> für Konfigurationstools).\n</li><li>Dient als Vorlage für die C-Code-Implementierung des BSW-Treibermoduls sowie die Definition der <code>TransformationTechnology</code> in der System Description (ARXML).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>API-Vertrag (<code>AUTOSAR_SWS_TransformerGeneral</code>):</strong>\n<ul class=\"fig-list\"><li>Die resultierende Spezifikation muss zwingend die standardisierten C-Funktionsprototypen gemäß AUTOSAR-Vorgabe vorschreiben:\n<ul class=\"fig-list\"><li>Vorwärtstransformation: <code>&lt;TransformerName&gt;_Transform(..., uint8* buffer, uint32* bufferLength, ...)</code>\n</li><li>Rückwärtstransformation: <code>&lt;TransformerName&gt;_InvTransform(..., const uint8* buffer, uint32 bufferLength, ...)</code>\n</li></ul>\n</li><li>Rückgabewerte müssen dem AUTOSAR-spezifischen Fehlerschema genügen (<code>E_OK</code>, <code>E_SER_GENERIC_ERROR</code>, herstellerspezifische Fehlerbits bzw. Severity-Klassen).\n</li></ul>\n</li><li><strong>Speicher- und Pufferstrategie:</strong>\n<ul class=\"fig-list\"><li>Klare Definition, ob der Transformer <em>in-place</em> (modifiziert den bestehenden Puffer) oder <em>out-of-place</em> (erfordert Allokation eines separaten Zielpuffers durch die RTE) arbeitet.\n</li><li>Im Embedded-Bereich müssen deterministische Obergrenzen für Puffergrößen (<code>bufferLength</code>) statisch zur Generierungszeit konfigurierbar sein; dynamische Speicherallokationen (<code>malloc</code>) sind strikt unzulässig.\n</li></ul>\n</li><li><strong>RTE-Integration &amp; Chain-Orchestrierung:</strong>\n<ul class=\"fig-list\"><li>Die RTE bindet Transformer-Aufrufe direkt in die Inline- oder Stub-Funktionen der Ports ein.\n</li><li>Sollen mehrere Transformer hintereinandergeschaltet werden (z. B. Custom-Serializer gefolgt von E2E-Protection), muss die Spezifikation die Position in der <code>TransformerChain</code> und die Pufferweitergabe mit den korrekten Alignment- und Padding-Restriktionen normieren.\n</li></ul>\n</li><li><strong>Reentrancy &amp; Interrupt-Sicherheit:</strong>\n<ul class=\"fig-list\"><li>Die Spezifikation muss festlegen, ob die Transformationsroutinen reentrant sein müssen, wenn dieselbe Transformer-Instanz parallel von unterschiedlichen SW-C-Tasks oder Interrupt-Kontexten aufgerufen werden kann.\n</li></ul>\n</li></ul>"}, {"id": "FIG-f8d3a779a163c3f3", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> SPEM 2.0 (Software &amp; Systems Process Engineering Metamodel) Task-Definitions- und Rollenzuweisungsdiagramm gemäß <code>AUTOSAR_TR_Methodology</code> (Package <code>AUTOSAR Root::M2::Methodology::Methodology Library::System::Tasks</code>).\n</li><li><strong>Architektur-Kontext:</strong> Methodische Verankerung im System- und Kommunikationsentwurf der AUTOSAR Classic Platform. Das Diagramm definiert den formalen Prozessschritt zur Erstellung der Spezifikation für anwenderspezifische Datentransformatoren (<em>Custom Transformers</em>). Diese erweitern die standardisierten RTE- und Kommunikationsmechanismen (z. B. SOME/IP-, E2E- oder SecOC-Transformer) um proprietäre Serialisierungs-, Kompressions-, Verschlüsselungs- oder Protokollanpassungslogik direkt im Datenpfad der RTE (<code>Rte_Send</code> / <code>Rte_Receive</code> bzw. <code>Rte_Write</code> / <code>Rte_Read</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Task Definition (Aktivitätsknoten):</strong>\n<ul class=\"fig-list\"><li><code>Create Transformer Specification</code>: Elementare SPEM-Aktivität (Chevron-Symbol). Kapselt die funktionale, mathematische und algorithmische Ausarbeitung des Verhaltens, des Frame-/Header-Layouts sowie der Schnittstellengeometrie des Transformers.\n</li></ul>\n</li><li><strong>Akteure / Rollen (SPEM Process Roles):</strong>\n<ul class=\"fig-list\"><li><code>System Engineer</code> (Akteur links): Primär verantwortlicher System- und Kommunikationsarchitekt; integriert die Transformationsanforderungen in die übergeordnete Signal-, Port- und Topologieplanung.\n</li><li><code>Basic Software Designer</code> (Akteur rechts): BSW-Architekt; liefert die hardware- und stacknahe Expertise bezüglich Laufzeiteffizienz, Speichermodellen und Betriebssystemkontexten.\n</li></ul>\n</li><li><strong>Arbeitsergebnis (SPEM Work Product / Deliverable):</strong>\n<ul class=\"fig-list\"><li><code>Custom Transformer Specification</code> (Dokumenten-Symbol unten rechts): Das verbindliche Spezifikationsdokument, welches als Entwicklungs- und Implementierungsgrundlage dient.\n</li></ul>\n</li><li><strong>Stereotypen, gerichtete Kanten &amp; Kardinalitäten:</strong>\n<ul class=\"fig-list\"><li><code>«performs»</code> von <code>System Engineer</code> zu <code>Create Transformer Specification</code> mit Kardinalität <code>1</code>: Obligatorische Federführung durch genau einen Systemingenieur.\n</li><li><code>«performs»</code> von <code>Basic Software Designer</code> zu <code>Create Transformer Specification</code> mit Kardinalität <code>0..1</code>: Optionale Mitwirkung zur Absicherung der Plattform- und BSW-Konformität.\n</li><li><code>«output»</code> von <code>Create Transformer Specification</code> zu <code>Custom Transformer Specification</code> mit Kardinalität <code>1</code>: Deterministisches Pflicht-Artefakt als Ergebnis der Task.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als SPEM-Strukturdiagramm bildet das Modell primär Prozessbeziehungen ab; die methodische Ausführung folgt folgendem deterministischen Ablauf:</p>\n<ol class=\"fig-list\"><li><strong>Trigger / Vorbedingung:</strong>\n<ul class=\"fig-list\"><li>Identifikation spezieller Datenübertragungsanforderungen im Systemdesign (z. B. Payload-Verschlüsselung, herstellerspezifische Prüfsummen oder Serialisierung komplexer Datentypen über Partitions- oder Busgrenzen hinweg), die nicht durch Standard-Transformer abgedeckt sind.\n</li></ul>\n</li><li><strong>Kollaborative Ausarbeitung (<code>Create Transformer Specification</code>):</strong>\n<ul class=\"fig-list\"><li><strong>System Engineer:</strong> Definiert das Protokollformat, Datenrepräsentationen, Serialisierungsregeln, Byte-Orderings, Pufferanforderungen und das Fehlerverhalten.\n</li><li><strong>Basic Software Designer (falls beteiligt, <code>0..1</code>):</strong> Validiert Pufferkonzepte (<em>in-place</em> vs. <em>out-of-place</em>), Reentrancy, Ausführungsbudgets im Kontext der OS-Tasks sowie die Stack-Auslastung.\n</li></ul>\n</li><li><strong>Artefakt-Erstellung (<code>«output» 1</code>):</strong>\n<ul class=\"fig-list\"><li>Generierung der <code>Custom Transformer Specification</code>.\n</li></ul>\n</li><li><strong>Nachgelagerte Prozessschritte (Downstream):</strong>\n<ul class=\"fig-list\"><li>Dient als direkte Eingabe für die Aktivität <code>Define Vendor Specific Module Definition</code> (Erstellung der BSWMD / <code>EcucModuleDef</code> für Konfigurationstools).\n</li><li>Dient als Vorlage für die C-Code-Implementierung des BSW-Treibermoduls sowie die Definition der <code>TransformationTechnology</code> in der System Description (ARXML).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>API-Vertrag (<code>AUTOSAR_SWS_TransformerGeneral</code>):</strong>\n<ul class=\"fig-list\"><li>Die resultierende Spezifikation muss zwingend die standardisierten C-Funktionsprototypen gemäß AUTOSAR-Vorgabe vorschreiben:\n<ul class=\"fig-list\"><li>Vorwärtstransformation: <code>&lt;TransformerName&gt;_Transform(..., uint8* buffer, uint32* bufferLength, ...)</code>\n</li><li>Rückwärtstransformation: <code>&lt;TransformerName&gt;_InvTransform(..., const uint8* buffer, uint32 bufferLength, ...)</code>\n</li></ul>\n</li><li>Rückgabewerte müssen dem AUTOSAR-spezifischen Fehlerschema genügen (<code>E_OK</code>, <code>E_SER_GENERIC_ERROR</code>, herstellerspezifische Fehlerbits bzw. Severity-Klassen).\n</li></ul>\n</li><li><strong>Speicher- und Pufferstrategie:</strong>\n<ul class=\"fig-list\"><li>Klare Definition, ob der Transformer <em>in-place</em> (modifiziert den bestehenden Puffer) oder <em>out-of-place</em> (erfordert Allokation eines separaten Zielpuffers durch die RTE) arbeitet.\n</li><li>Im Embedded-Bereich müssen deterministische Obergrenzen für Puffergrößen (<code>bufferLength</code>) statisch zur Generierungszeit konfigurierbar sein; dynamische Speicherallokationen (<code>malloc</code>) sind strikt unzulässig.\n</li></ul>\n</li><li><strong>RTE-Integration &amp; Chain-Orchestrierung:</strong>\n<ul class=\"fig-list\"><li>Die RTE bindet Transformer-Aufrufe direkt in die Inline- oder Stub-Funktionen der Ports ein.\n</li><li>Sollen mehrere Transformer hintereinandergeschaltet werden (z. B. Custom-Serializer gefolgt von E2E-Protection), muss die Spezifikation die Position in der <code>TransformerChain</code> und die Pufferweitergabe mit den korrekten Alignment- und Padding-Restriktionen normieren.\n</li></ul>\n</li><li><strong>Reentrancy &amp; Interrupt-Sicherheit:</strong>\n<ul class=\"fig-list\"><li>Die Spezifikation muss festlegen, ob die Transformationsroutinen reentrant sein müssen, wenn dieselbe Transformer-Instanz parallel von unterschiedlichen SW-C-Tasks oder Interrupt-Kontexten aufgerufen werden kann.\n</li></ul>\n</li></ul>"}, {"id": "FIG-caa5077ee62e54b6", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> SPEM 2.0 (Software &amp; Systems Process Engineering Metamodel) Task-Definitions- und Rollenzuweisungsdiagramm gemäß <code>AUTOSAR_TR_Methodology</code> (Package <code>AUTOSAR Root::M2::Methodology::Methodology Library::System::Tasks</code>).\n</li><li><strong>Architektur-Kontext:</strong> Methodische Verankerung im System- und Kommunikationsentwurf der AUTOSAR Classic Platform. Das Diagramm definiert den formalen Prozessschritt zur Erstellung der Spezifikation für anwenderspezifische Datentransformatoren (<em>Custom Transformers</em>). Diese erweitern die standardisierten RTE- und Kommunikationsmechanismen (z. B. SOME/IP-, E2E- oder SecOC-Transformer) um proprietäre Serialisierungs-, Kompressions-, Verschlüsselungs- oder Protokollanpassungslogik direkt im Datenpfad der RTE (<code>Rte_Send</code> / <code>Rte_Receive</code> bzw. <code>Rte_Write</code> / <code>Rte_Read</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Task Definition (Aktivitätsknoten):</strong>\n<ul class=\"fig-list\"><li><code>Create Transformer Specification</code>: Elementare SPEM-Aktivität (Chevron-Symbol). Kapselt die funktionale, mathematische und algorithmische Ausarbeitung des Verhaltens, des Frame-/Header-Layouts sowie der Schnittstellengeometrie des Transformers.\n</li></ul>\n</li><li><strong>Akteure / Rollen (SPEM Process Roles):</strong>\n<ul class=\"fig-list\"><li><code>System Engineer</code> (Akteur links): Primär verantwortlicher System- und Kommunikationsarchitekt; integriert die Transformationsanforderungen in die übergeordnete Signal-, Port- und Topologieplanung.\n</li><li><code>Basic Software Designer</code> (Akteur rechts): BSW-Architekt; liefert die hardware- und stacknahe Expertise bezüglich Laufzeiteffizienz, Speichermodellen und Betriebssystemkontexten.\n</li></ul>\n</li><li><strong>Arbeitsergebnis (SPEM Work Product / Deliverable):</strong>\n<ul class=\"fig-list\"><li><code>Custom Transformer Specification</code> (Dokumenten-Symbol unten rechts): Das verbindliche Spezifikationsdokument, welches als Entwicklungs- und Implementierungsgrundlage dient.\n</li></ul>\n</li><li><strong>Stereotypen, gerichtete Kanten &amp; Kardinalitäten:</strong>\n<ul class=\"fig-list\"><li><code>«performs»</code> von <code>System Engineer</code> zu <code>Create Transformer Specification</code> mit Kardinalität <code>1</code>: Obligatorische Federführung durch genau einen Systemingenieur.\n</li><li><code>«performs»</code> von <code>Basic Software Designer</code> zu <code>Create Transformer Specification</code> mit Kardinalität <code>0..1</code>: Optionale Mitwirkung zur Absicherung der Plattform- und BSW-Konformität.\n</li><li><code>«output»</code> von <code>Create Transformer Specification</code> zu <code>Custom Transformer Specification</code> mit Kardinalität <code>1</code>: Deterministisches Pflicht-Artefakt als Ergebnis der Task.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als SPEM-Strukturdiagramm bildet das Modell primär Prozessbeziehungen ab; die methodische Ausführung folgt folgendem deterministischen Ablauf:</p>\n<ol class=\"fig-list\"><li><strong>Trigger / Vorbedingung:</strong>\n<ul class=\"fig-list\"><li>Identifikation spezieller Datenübertragungsanforderungen im Systemdesign (z. B. Payload-Verschlüsselung, herstellerspezifische Prüfsummen oder Serialisierung komplexer Datentypen über Partitions- oder Busgrenzen hinweg), die nicht durch Standard-Transformer abgedeckt sind.\n</li></ul>\n</li><li><strong>Kollaborative Ausarbeitung (<code>Create Transformer Specification</code>):</strong>\n<ul class=\"fig-list\"><li><strong>System Engineer:</strong> Definiert das Protokollformat, Datenrepräsentationen, Serialisierungsregeln, Byte-Orderings, Pufferanforderungen und das Fehlerverhalten.\n</li><li><strong>Basic Software Designer (falls beteiligt, <code>0..1</code>):</strong> Validiert Pufferkonzepte (<em>in-place</em> vs. <em>out-of-place</em>), Reentrancy, Ausführungsbudgets im Kontext der OS-Tasks sowie die Stack-Auslastung.\n</li></ul>\n</li><li><strong>Artefakt-Erstellung (<code>«output» 1</code>):</strong>\n<ul class=\"fig-list\"><li>Generierung der <code>Custom Transformer Specification</code>.\n</li></ul>\n</li><li><strong>Nachgelagerte Prozessschritte (Downstream):</strong>\n<ul class=\"fig-list\"><li>Dient als direkte Eingabe für die Aktivität <code>Define Vendor Specific Module Definition</code> (Erstellung der BSWMD / <code>EcucModuleDef</code> für Konfigurationstools).\n</li><li>Dient als Vorlage für die C-Code-Implementierung des BSW-Treibermoduls sowie die Definition der <code>TransformationTechnology</code> in der System Description (ARXML).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>API-Vertrag (<code>AUTOSAR_SWS_TransformerGeneral</code>):</strong>\n<ul class=\"fig-list\"><li>Die resultierende Spezifikation muss zwingend die standardisierten C-Funktionsprototypen gemäß AUTOSAR-Vorgabe vorschreiben:\n<ul class=\"fig-list\"><li>Vorwärtstransformation: <code>&lt;TransformerName&gt;_Transform(..., uint8* buffer, uint32* bufferLength, ...)</code>\n</li><li>Rückwärtstransformation: <code>&lt;TransformerName&gt;_InvTransform(..., const uint8* buffer, uint32 bufferLength, ...)</code>\n</li></ul>\n</li><li>Rückgabewerte müssen dem AUTOSAR-spezifischen Fehlerschema genügen (<code>E_OK</code>, <code>E_SER_GENERIC_ERROR</code>, herstellerspezifische Fehlerbits bzw. Severity-Klassen).\n</li></ul>\n</li><li><strong>Speicher- und Pufferstrategie:</strong>\n<ul class=\"fig-list\"><li>Klare Definition, ob der Transformer <em>in-place</em> (modifiziert den bestehenden Puffer) oder <em>out-of-place</em> (erfordert Allokation eines separaten Zielpuffers durch die RTE) arbeitet.\n</li><li>Im Embedded-Bereich müssen deterministische Obergrenzen für Puffergrößen (<code>bufferLength</code>) statisch zur Generierungszeit konfigurierbar sein; dynamische Speicherallokationen (<code>malloc</code>) sind strikt unzulässig.\n</li></ul>\n</li><li><strong>RTE-Integration &amp; Chain-Orchestrierung:</strong>\n<ul class=\"fig-list\"><li>Die RTE bindet Transformer-Aufrufe direkt in die Inline- oder Stub-Funktionen der Ports ein.\n</li><li>Sollen mehrere Transformer hintereinandergeschaltet werden (z. B. Custom-Serializer gefolgt von E2E-Protection), muss die Spezifikation die Position in der <code>TransformerChain</code> und die Pufferweitergabe mit den korrekten Alignment- und Padding-Restriktionen normieren.\n</li></ul>\n</li><li><strong>Reentrancy &amp; Interrupt-Sicherheit:</strong>\n<ul class=\"fig-list\"><li>Die Spezifikation muss festlegen, ob die Transformationsroutinen reentrant sein müssen, wenn dieselbe Transformer-Instanz parallel von unterschiedlichen SW-C-Tasks oder Interrupt-Kontexten aufgerufen werden kann.\n</li></ul>\n</li></ul>"}, {"id": "FIG-e8840ab7d52d8fa0", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> SPEM 2.0 (Software &amp; Systems Process Engineering Metamodel) Task-Definitions- und Rollenzuweisungsdiagramm gemäß <code>AUTOSAR_TR_Methodology</code> (Package <code>AUTOSAR Root::M2::Methodology::Methodology Library::System::Tasks</code>).\n</li><li><strong>Architektur-Kontext:</strong> Methodische Verankerung im System- und Kommunikationsentwurf der AUTOSAR Classic Platform. Das Diagramm definiert den formalen Prozessschritt zur Erstellung der Spezifikation für anwenderspezifische Datentransformatoren (<em>Custom Transformers</em>). Diese erweitern die standardisierten RTE- und Kommunikationsmechanismen (z. B. SOME/IP-, E2E- oder SecOC-Transformer) um proprietäre Serialisierungs-, Kompressions-, Verschlüsselungs- oder Protokollanpassungslogik direkt im Datenpfad der RTE (<code>Rte_Send</code> / <code>Rte_Receive</code> bzw. <code>Rte_Write</code> / <code>Rte_Read</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Task Definition (Aktivitätsknoten):</strong>\n<ul class=\"fig-list\"><li><code>Create Transformer Specification</code>: Elementare SPEM-Aktivität (Chevron-Symbol). Kapselt die funktionale, mathematische und algorithmische Ausarbeitung des Verhaltens, des Frame-/Header-Layouts sowie der Schnittstellengeometrie des Transformers.\n</li></ul>\n</li><li><strong>Akteure / Rollen (SPEM Process Roles):</strong>\n<ul class=\"fig-list\"><li><code>System Engineer</code> (Akteur links): Primär verantwortlicher System- und Kommunikationsarchitekt; integriert die Transformationsanforderungen in die übergeordnete Signal-, Port- und Topologieplanung.\n</li><li><code>Basic Software Designer</code> (Akteur rechts): BSW-Architekt; liefert die hardware- und stacknahe Expertise bezüglich Laufzeiteffizienz, Speichermodellen und Betriebssystemkontexten.\n</li></ul>\n</li><li><strong>Arbeitsergebnis (SPEM Work Product / Deliverable):</strong>\n<ul class=\"fig-list\"><li><code>Custom Transformer Specification</code> (Dokumenten-Symbol unten rechts): Das verbindliche Spezifikationsdokument, welches als Entwicklungs- und Implementierungsgrundlage dient.\n</li></ul>\n</li><li><strong>Stereotypen, gerichtete Kanten &amp; Kardinalitäten:</strong>\n<ul class=\"fig-list\"><li><code>«performs»</code> von <code>System Engineer</code> zu <code>Create Transformer Specification</code> mit Kardinalität <code>1</code>: Obligatorische Federführung durch genau einen Systemingenieur.\n</li><li><code>«performs»</code> von <code>Basic Software Designer</code> zu <code>Create Transformer Specification</code> mit Kardinalität <code>0..1</code>: Optionale Mitwirkung zur Absicherung der Plattform- und BSW-Konformität.\n</li><li><code>«output»</code> von <code>Create Transformer Specification</code> zu <code>Custom Transformer Specification</code> mit Kardinalität <code>1</code>: Deterministisches Pflicht-Artefakt als Ergebnis der Task.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als SPEM-Strukturdiagramm bildet das Modell primär Prozessbeziehungen ab; die methodische Ausführung folgt folgendem deterministischen Ablauf:</p>\n<ol class=\"fig-list\"><li><strong>Trigger / Vorbedingung:</strong>\n<ul class=\"fig-list\"><li>Identifikation spezieller Datenübertragungsanforderungen im Systemdesign (z. B. Payload-Verschlüsselung, herstellerspezifische Prüfsummen oder Serialisierung komplexer Datentypen über Partitions- oder Busgrenzen hinweg), die nicht durch Standard-Transformer abgedeckt sind.\n</li></ul>\n</li><li><strong>Kollaborative Ausarbeitung (<code>Create Transformer Specification</code>):</strong>\n<ul class=\"fig-list\"><li><strong>System Engineer:</strong> Definiert das Protokollformat, Datenrepräsentationen, Serialisierungsregeln, Byte-Orderings, Pufferanforderungen und das Fehlerverhalten.\n</li><li><strong>Basic Software Designer (falls beteiligt, <code>0..1</code>):</strong> Validiert Pufferkonzepte (<em>in-place</em> vs. <em>out-of-place</em>), Reentrancy, Ausführungsbudgets im Kontext der OS-Tasks sowie die Stack-Auslastung.\n</li></ul>\n</li><li><strong>Artefakt-Erstellung (<code>«output» 1</code>):</strong>\n<ul class=\"fig-list\"><li>Generierung der <code>Custom Transformer Specification</code>.\n</li></ul>\n</li><li><strong>Nachgelagerte Prozessschritte (Downstream):</strong>\n<ul class=\"fig-list\"><li>Dient als direkte Eingabe für die Aktivität <code>Define Vendor Specific Module Definition</code> (Erstellung der BSWMD / <code>EcucModuleDef</code> für Konfigurationstools).\n</li><li>Dient als Vorlage für die C-Code-Implementierung des BSW-Treibermoduls sowie die Definition der <code>TransformationTechnology</code> in der System Description (ARXML).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>API-Vertrag (<code>AUTOSAR_SWS_TransformerGeneral</code>):</strong>\n<ul class=\"fig-list\"><li>Die resultierende Spezifikation muss zwingend die standardisierten C-Funktionsprototypen gemäß AUTOSAR-Vorgabe vorschreiben:\n<ul class=\"fig-list\"><li>Vorwärtstransformation: <code>&lt;TransformerName&gt;_Transform(..., uint8* buffer, uint32* bufferLength, ...)</code>\n</li><li>Rückwärtstransformation: <code>&lt;TransformerName&gt;_InvTransform(..., const uint8* buffer, uint32 bufferLength, ...)</code>\n</li></ul>\n</li><li>Rückgabewerte müssen dem AUTOSAR-spezifischen Fehlerschema genügen (<code>E_OK</code>, <code>E_SER_GENERIC_ERROR</code>, herstellerspezifische Fehlerbits bzw. Severity-Klassen).\n</li></ul>\n</li><li><strong>Speicher- und Pufferstrategie:</strong>\n<ul class=\"fig-list\"><li>Klare Definition, ob der Transformer <em>in-place</em> (modifiziert den bestehenden Puffer) oder <em>out-of-place</em> (erfordert Allokation eines separaten Zielpuffers durch die RTE) arbeitet.\n</li><li>Im Embedded-Bereich müssen deterministische Obergrenzen für Puffergrößen (<code>bufferLength</code>) statisch zur Generierungszeit konfigurierbar sein; dynamische Speicherallokationen (<code>malloc</code>) sind strikt unzulässig.\n</li></ul>\n</li><li><strong>RTE-Integration &amp; Chain-Orchestrierung:</strong>\n<ul class=\"fig-list\"><li>Die RTE bindet Transformer-Aufrufe direkt in die Inline- oder Stub-Funktionen der Ports ein.\n</li><li>Sollen mehrere Transformer hintereinandergeschaltet werden (z. B. Custom-Serializer gefolgt von E2E-Protection), muss die Spezifikation die Position in der <code>TransformerChain</code> und die Pufferweitergabe mit den korrekten Alignment- und Padding-Restriktionen normieren.\n</li></ul>\n</li><li><strong>Reentrancy &amp; Interrupt-Sicherheit:</strong>\n<ul class=\"fig-list\"><li>Die Spezifikation muss festlegen, ob die Transformationsroutinen reentrant sein müssen, wenn dieselbe Transformer-Instanz parallel von unterschiedlichen SW-C-Tasks oder Interrupt-Kontexten aufgerufen werden kann.\n</li></ul>\n</li></ul>"}, {"id": "FIG-e057cd2867c3f998", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> SPEM 2.0 (Software &amp; Systems Process Engineering Metamodel) Task-Definitions- und Rollenzuweisungsdiagramm gemäß <code>AUTOSAR_TR_Methodology</code> (Package <code>AUTOSAR Root::M2::Methodology::Methodology Library::System::Tasks</code>).\n</li><li><strong>Architektur-Kontext:</strong> Methodische Verankerung im System- und Kommunikationsentwurf der AUTOSAR Classic Platform. Das Diagramm definiert den formalen Prozessschritt zur Erstellung der Spezifikation für anwenderspezifische Datentransformatoren (<em>Custom Transformers</em>). Diese erweitern die standardisierten RTE- und Kommunikationsmechanismen (z. B. SOME/IP-, E2E- oder SecOC-Transformer) um proprietäre Serialisierungs-, Kompressions-, Verschlüsselungs- oder Protokollanpassungslogik direkt im Datenpfad der RTE (<code>Rte_Send</code> / <code>Rte_Receive</code> bzw. <code>Rte_Write</code> / <code>Rte_Read</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Task Definition (Aktivitätsknoten):</strong>\n<ul class=\"fig-list\"><li><code>Create Transformer Specification</code>: Elementare SPEM-Aktivität (Chevron-Symbol). Kapselt die funktionale, mathematische und algorithmische Ausarbeitung des Verhaltens, des Frame-/Header-Layouts sowie der Schnittstellengeometrie des Transformers.\n</li></ul>\n</li><li><strong>Akteure / Rollen (SPEM Process Roles):</strong>\n<ul class=\"fig-list\"><li><code>System Engineer</code> (Akteur links): Primär verantwortlicher System- und Kommunikationsarchitekt; integriert die Transformationsanforderungen in die übergeordnete Signal-, Port- und Topologieplanung.\n</li><li><code>Basic Software Designer</code> (Akteur rechts): BSW-Architekt; liefert die hardware- und stacknahe Expertise bezüglich Laufzeiteffizienz, Speichermodellen und Betriebssystemkontexten.\n</li></ul>\n</li><li><strong>Arbeitsergebnis (SPEM Work Product / Deliverable):</strong>\n<ul class=\"fig-list\"><li><code>Custom Transformer Specification</code> (Dokumenten-Symbol unten rechts): Das verbindliche Spezifikationsdokument, welches als Entwicklungs- und Implementierungsgrundlage dient.\n</li></ul>\n</li><li><strong>Stereotypen, gerichtete Kanten &amp; Kardinalitäten:</strong>\n<ul class=\"fig-list\"><li><code>«performs»</code> von <code>System Engineer</code> zu <code>Create Transformer Specification</code> mit Kardinalität <code>1</code>: Obligatorische Federführung durch genau einen Systemingenieur.\n</li><li><code>«performs»</code> von <code>Basic Software Designer</code> zu <code>Create Transformer Specification</code> mit Kardinalität <code>0..1</code>: Optionale Mitwirkung zur Absicherung der Plattform- und BSW-Konformität.\n</li><li><code>«output»</code> von <code>Create Transformer Specification</code> zu <code>Custom Transformer Specification</code> mit Kardinalität <code>1</code>: Deterministisches Pflicht-Artefakt als Ergebnis der Task.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als SPEM-Strukturdiagramm bildet das Modell primär Prozessbeziehungen ab; die methodische Ausführung folgt folgendem deterministischen Ablauf:</p>\n<ol class=\"fig-list\"><li><strong>Trigger / Vorbedingung:</strong>\n<ul class=\"fig-list\"><li>Identifikation spezieller Datenübertragungsanforderungen im Systemdesign (z. B. Payload-Verschlüsselung, herstellerspezifische Prüfsummen oder Serialisierung komplexer Datentypen über Partitions- oder Busgrenzen hinweg), die nicht durch Standard-Transformer abgedeckt sind.\n</li></ul>\n</li><li><strong>Kollaborative Ausarbeitung (<code>Create Transformer Specification</code>):</strong>\n<ul class=\"fig-list\"><li><strong>System Engineer:</strong> Definiert das Protokollformat, Datenrepräsentationen, Serialisierungsregeln, Byte-Orderings, Pufferanforderungen und das Fehlerverhalten.\n</li><li><strong>Basic Software Designer (falls beteiligt, <code>0..1</code>):</strong> Validiert Pufferkonzepte (<em>in-place</em> vs. <em>out-of-place</em>), Reentrancy, Ausführungsbudgets im Kontext der OS-Tasks sowie die Stack-Auslastung.\n</li></ul>\n</li><li><strong>Artefakt-Erstellung (<code>«output» 1</code>):</strong>\n<ul class=\"fig-list\"><li>Generierung der <code>Custom Transformer Specification</code>.\n</li></ul>\n</li><li><strong>Nachgelagerte Prozessschritte (Downstream):</strong>\n<ul class=\"fig-list\"><li>Dient als direkte Eingabe für die Aktivität <code>Define Vendor Specific Module Definition</code> (Erstellung der BSWMD / <code>EcucModuleDef</code> für Konfigurationstools).\n</li><li>Dient als Vorlage für die C-Code-Implementierung des BSW-Treibermoduls sowie die Definition der <code>TransformationTechnology</code> in der System Description (ARXML).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>API-Vertrag (<code>AUTOSAR_SWS_TransformerGeneral</code>):</strong>\n<ul class=\"fig-list\"><li>Die resultierende Spezifikation muss zwingend die standardisierten C-Funktionsprototypen gemäß AUTOSAR-Vorgabe vorschreiben:\n<ul class=\"fig-list\"><li>Vorwärtstransformation: <code>&lt;TransformerName&gt;_Transform(..., uint8* buffer, uint32* bufferLength, ...)</code>\n</li><li>Rückwärtstransformation: <code>&lt;TransformerName&gt;_InvTransform(..., const uint8* buffer, uint32 bufferLength, ...)</code>\n</li></ul>\n</li><li>Rückgabewerte müssen dem AUTOSAR-spezifischen Fehlerschema genügen (<code>E_OK</code>, <code>E_SER_GENERIC_ERROR</code>, herstellerspezifische Fehlerbits bzw. Severity-Klassen).\n</li></ul>\n</li><li><strong>Speicher- und Pufferstrategie:</strong>\n<ul class=\"fig-list\"><li>Klare Definition, ob der Transformer <em>in-place</em> (modifiziert den bestehenden Puffer) oder <em>out-of-place</em> (erfordert Allokation eines separaten Zielpuffers durch die RTE) arbeitet.\n</li><li>Im Embedded-Bereich müssen deterministische Obergrenzen für Puffergrößen (<code>bufferLength</code>) statisch zur Generierungszeit konfigurierbar sein; dynamische Speicherallokationen (<code>malloc</code>) sind strikt unzulässig.\n</li></ul>\n</li><li><strong>RTE-Integration &amp; Chain-Orchestrierung:</strong>\n<ul class=\"fig-list\"><li>Die RTE bindet Transformer-Aufrufe direkt in die Inline- oder Stub-Funktionen der Ports ein.\n</li><li>Sollen mehrere Transformer hintereinandergeschaltet werden (z. B. Custom-Serializer gefolgt von E2E-Protection), muss die Spezifikation die Position in der <code>TransformerChain</code> und die Pufferweitergabe mit den korrekten Alignment- und Padding-Restriktionen normieren.\n</li></ul>\n</li><li><strong>Reentrancy &amp; Interrupt-Sicherheit:</strong>\n<ul class=\"fig-list\"><li>Die Spezifikation muss festlegen, ob die Transformationsroutinen reentrant sein müssen, wenn dieselbe Transformer-Instanz parallel von unterschiedlichen SW-C-Tasks oder Interrupt-Kontexten aufgerufen werden kann.\n</li></ul>\n</li></ul>"}, {"id": "FIG-7f831f8f89232687", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> SPEM 2.0 (Software &amp; Systems Process Engineering Metamodel) Task-Definitions- und Rollenzuweisungsdiagramm gemäß <code>AUTOSAR_TR_Methodology</code> (Package <code>AUTOSAR Root::M2::Methodology::Methodology Library::System::Tasks</code>).\n</li><li><strong>Architektur-Kontext:</strong> Methodische Verankerung im System- und Kommunikationsentwurf der AUTOSAR Classic Platform. Das Diagramm definiert den formalen Prozessschritt zur Erstellung der Spezifikation für anwenderspezifische Datentransformatoren (<em>Custom Transformers</em>). Diese erweitern die standardisierten RTE- und Kommunikationsmechanismen (z. B. SOME/IP-, E2E- oder SecOC-Transformer) um proprietäre Serialisierungs-, Kompressions-, Verschlüsselungs- oder Protokollanpassungslogik direkt im Datenpfad der RTE (<code>Rte_Send</code> / <code>Rte_Receive</code> bzw. <code>Rte_Write</code> / <code>Rte_Read</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Task Definition (Aktivitätsknoten):</strong>\n<ul class=\"fig-list\"><li><code>Create Transformer Specification</code>: Elementare SPEM-Aktivität (Chevron-Symbol). Kapselt die funktionale, mathematische und algorithmische Ausarbeitung des Verhaltens, des Frame-/Header-Layouts sowie der Schnittstellengeometrie des Transformers.\n</li></ul>\n</li><li><strong>Akteure / Rollen (SPEM Process Roles):</strong>\n<ul class=\"fig-list\"><li><code>System Engineer</code> (Akteur links): Primär verantwortlicher System- und Kommunikationsarchitekt; integriert die Transformationsanforderungen in die übergeordnete Signal-, Port- und Topologieplanung.\n</li><li><code>Basic Software Designer</code> (Akteur rechts): BSW-Architekt; liefert die hardware- und stacknahe Expertise bezüglich Laufzeiteffizienz, Speichermodellen und Betriebssystemkontexten.\n</li></ul>\n</li><li><strong>Arbeitsergebnis (SPEM Work Product / Deliverable):</strong>\n<ul class=\"fig-list\"><li><code>Custom Transformer Specification</code> (Dokumenten-Symbol unten rechts): Das verbindliche Spezifikationsdokument, welches als Entwicklungs- und Implementierungsgrundlage dient.\n</li></ul>\n</li><li><strong>Stereotypen, gerichtete Kanten &amp; Kardinalitäten:</strong>\n<ul class=\"fig-list\"><li><code>«performs»</code> von <code>System Engineer</code> zu <code>Create Transformer Specification</code> mit Kardinalität <code>1</code>: Obligatorische Federführung durch genau einen Systemingenieur.\n</li><li><code>«performs»</code> von <code>Basic Software Designer</code> zu <code>Create Transformer Specification</code> mit Kardinalität <code>0..1</code>: Optionale Mitwirkung zur Absicherung der Plattform- und BSW-Konformität.\n</li><li><code>«output»</code> von <code>Create Transformer Specification</code> zu <code>Custom Transformer Specification</code> mit Kardinalität <code>1</code>: Deterministisches Pflicht-Artefakt als Ergebnis der Task.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als SPEM-Strukturdiagramm bildet das Modell primär Prozessbeziehungen ab; die methodische Ausführung folgt folgendem deterministischen Ablauf:</p>\n<ol class=\"fig-list\"><li><strong>Trigger / Vorbedingung:</strong>\n<ul class=\"fig-list\"><li>Identifikation spezieller Datenübertragungsanforderungen im Systemdesign (z. B. Payload-Verschlüsselung, herstellerspezifische Prüfsummen oder Serialisierung komplexer Datentypen über Partitions- oder Busgrenzen hinweg), die nicht durch Standard-Transformer abgedeckt sind.\n</li></ul>\n</li><li><strong>Kollaborative Ausarbeitung (<code>Create Transformer Specification</code>):</strong>\n<ul class=\"fig-list\"><li><strong>System Engineer:</strong> Definiert das Protokollformat, Datenrepräsentationen, Serialisierungsregeln, Byte-Orderings, Pufferanforderungen und das Fehlerverhalten.\n</li><li><strong>Basic Software Designer (falls beteiligt, <code>0..1</code>):</strong> Validiert Pufferkonzepte (<em>in-place</em> vs. <em>out-of-place</em>), Reentrancy, Ausführungsbudgets im Kontext der OS-Tasks sowie die Stack-Auslastung.\n</li></ul>\n</li><li><strong>Artefakt-Erstellung (<code>«output» 1</code>):</strong>\n<ul class=\"fig-list\"><li>Generierung der <code>Custom Transformer Specification</code>.\n</li></ul>\n</li><li><strong>Nachgelagerte Prozessschritte (Downstream):</strong>\n<ul class=\"fig-list\"><li>Dient als direkte Eingabe für die Aktivität <code>Define Vendor Specific Module Definition</code> (Erstellung der BSWMD / <code>EcucModuleDef</code> für Konfigurationstools).\n</li><li>Dient als Vorlage für die C-Code-Implementierung des BSW-Treibermoduls sowie die Definition der <code>TransformationTechnology</code> in der System Description (ARXML).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>API-Vertrag (<code>AUTOSAR_SWS_TransformerGeneral</code>):</strong>\n<ul class=\"fig-list\"><li>Die resultierende Spezifikation muss zwingend die standardisierten C-Funktionsprototypen gemäß AUTOSAR-Vorgabe vorschreiben:\n<ul class=\"fig-list\"><li>Vorwärtstransformation: <code>&lt;TransformerName&gt;_Transform(..., uint8* buffer, uint32* bufferLength, ...)</code>\n</li><li>Rückwärtstransformation: <code>&lt;TransformerName&gt;_InvTransform(..., const uint8* buffer, uint32 bufferLength, ...)</code>\n</li></ul>\n</li><li>Rückgabewerte müssen dem AUTOSAR-spezifischen Fehlerschema genügen (<code>E_OK</code>, <code>E_SER_GENERIC_ERROR</code>, herstellerspezifische Fehlerbits bzw. Severity-Klassen).\n</li></ul>\n</li><li><strong>Speicher- und Pufferstrategie:</strong>\n<ul class=\"fig-list\"><li>Klare Definition, ob der Transformer <em>in-place</em> (modifiziert den bestehenden Puffer) oder <em>out-of-place</em> (erfordert Allokation eines separaten Zielpuffers durch die RTE) arbeitet.\n</li><li>Im Embedded-Bereich müssen deterministische Obergrenzen für Puffergrößen (<code>bufferLength</code>) statisch zur Generierungszeit konfigurierbar sein; dynamische Speicherallokationen (<code>malloc</code>) sind strikt unzulässig.\n</li></ul>\n</li><li><strong>RTE-Integration &amp; Chain-Orchestrierung:</strong>\n<ul class=\"fig-list\"><li>Die RTE bindet Transformer-Aufrufe direkt in die Inline- oder Stub-Funktionen der Ports ein.\n</li><li>Sollen mehrere Transformer hintereinandergeschaltet werden (z. B. Custom-Serializer gefolgt von E2E-Protection), muss die Spezifikation die Position in der <code>TransformerChain</code> und die Pufferweitergabe mit den korrekten Alignment- und Padding-Restriktionen normieren.\n</li></ul>\n</li><li><strong>Reentrancy &amp; Interrupt-Sicherheit:</strong>\n<ul class=\"fig-list\"><li>Die Spezifikation muss festlegen, ob die Transformationsroutinen reentrant sein müssen, wenn dieselbe Transformer-Instanz parallel von unterschiedlichen SW-C-Tasks oder Interrupt-Kontexten aufgerufen werden kann.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-68dde4c4b6a40b10", "to": "FIG-ce92223d344d2fc8", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-ce92223d344d2fc8", "to": "FIG-f8d3a779a163c3f3", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-f8d3a779a163c3f3", "to": "FIG-ce92223d344d2fc8", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-ce92223d344d2fc8", "to": "FIG-caa5077ee62e54b6", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-caa5077ee62e54b6", "to": "FIG-e8840ab7d52d8fa0", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-e8840ab7d52d8fa0", "to": "FIG-e057cd2867c3f998", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Akteur links: Rollenbezeichnung <code>System Engineer</code> oberhalb/neben der Figur wieder sichtbar im Bildbereich platziert.\n</li><li>Akteur rechts: Rollenbezeichnung <code>Basic Software Designer</code> am rechten Bildrand leicht abgeschnitten (<code>Ba...</code>).\n</li><li>Layout: Breiteres Seitenverhältnis und Neuanordnung der Elemente mit veränderten Pfeillängen.\n</li></ul>"}, {"from": "FIG-e057cd2867c3f998", "to": "FIG-7f831f8f89232687", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
